# Generated by build.py from recipe.yml for recipe coap-watch-a-resource-change. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/thermostat.txt'), "setpoint=68")
[IO.File]::WriteAllText((Join-Path $PWD 'new.txt'), "setpoint=70")
[IO.File]::WriteAllText((Join-Path $PWD 'observe.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh observe.sh COAP_PORT HTTP_PORT HOW SECONDS. The gateway observes thermostat.txt with`n# curl --coap-observe, writing each representation it is sent to seen.txt, a line each. Once it holds`n# the first, the file is replaced with new.txt by HOW: coap (a CoAP PUT), http (an HTTP PUT) or`n# delete (a CoAP DELETE). Then it waits at most SECONDS for the gateway to see the change and prints`n# what the gateway saw.`ncoap=`"coap://127.0.0.1:`$1/thermostat.txt`"`nrm -f seen.txt`ncurl -s -m 90 --coap-observe `"`$coap`" -o seen.txt &`ngateway=`$!`ntries=0`nuntil [ -s seen.txt ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 20 ]; then echo `"the gateway was not registered within 10 s`" >&2; kill `"`$gateway`"; exit 1; fi`n  sleep 0.5`ndone`ncase `"`$3`" in`n  coap) curl -s -X PUT -d @new.txt `"`$coap`" ;;`n  http) curl -s -T new.txt `"http://127.0.0.1:`$2/thermostat.txt`" ;;`n  delete) curl -s -X DELETE `"`$coap`"; wait `"`$gateway`"; echo `"the gateway ended by itself, exit `$?`"; cat seen.txt; exit 0 ;;`nesac`ntries=0`nuntil [ `"`$(grep -c . seen.txt)`" -ge 2 ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt `$((`$4 * 2)) ]; then break; fi`n  sleep 0.5`ndone`nkill `"`$gateway`"`ncat seen.txt`nif [ `"`$(grep -c . seen.txt)`" -lt 2 ]; then echo `"no change seen within `$4 s`"; fi`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-anonymous', '--allow-uploads', 'coap://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh observe.sh 8080 8081 coap 10 } finally { Stop-Process $server0 }
